// Веб-версия (docs/app): вход по токену GitHub, «Свой ключ YouTube», «Видео — в приложении», «Сообщество недоступно: не задан ключ YouTube». Запуск: node design/prototype/web.test.js [shots]
const {chromium}=require('playwright');const path=require('path');
const IDX='file://'+path.join(__dirname,'index.html');const OUT=path.join(__dirname,'..','screenshots')+'/';const shots=process.argv[2]==='shots';
(async()=>{const b=await chromium.launch();let fails=0;
// Телефон без мобильного UA: веб-версия в мобильном браузере, платформа прототипа по умолчанию
const V=[['ПК 1440×900',{viewport:{width:1440,height:900}},''],['телефон 390×844',{viewport:{width:390,height:844},isMobile:true,hasTouch:true},'phone-']];
for(const th of (shots?['dark','light']:['dark']))for(const [vn,o,k] of V){const ctx=await b.newContext({...o,colorScheme:th});const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));
 const ev=(f,a)=>p.evaluate(f,a);
 const click=async s=>{const l=p.locator(s).first();if(o.hasTouch)await l.tap({timeout:3000});else{await l.hover({force:true});await l.click({timeout:3000});}await p.waitForTimeout(250)};
 const sel=async(id,v)=>{await ev(([id,v])=>{const s=document.querySelector('#'+id);s.value=v;s.dispatchEvent(new Event('change',{bubbles:true}))},[id,v]);await p.waitForTimeout(250)};
 const go=async h=>{await ev(()=>{location.hash='search'});await p.waitForTimeout(120);await ev(h=>{location.hash=h},h);await p.waitForTimeout(350)};
 const shot=async n=>{await ev(()=>document.querySelectorAll('.toast').forEach(t=>t.remove()));if(shots)await p.screenshot({path:OUT+n+'-'+k+th+'.png'})};
 const txt=s=>ev(s=>(document.querySelector(s)||{}).textContent||'',s);
 const noHscroll=()=>ev(()=>document.documentElement.scrollWidth<=innerWidth&&document.querySelector('#main').scrollWidth<=document.querySelector('#main').clientWidth);
 const res=[];const T=async(n,f)=>{try{res.push([n,(await f())?'OK':'FAIL'])}catch(e){res.push([n,'FAIL '+e.message.split('\n')[0].slice(0,80)])}};
 await p.goto(IDX+'#catalog');await p.waitForTimeout(500);
 await sel('demoBuild','web');await ev(()=>{prof().gh=null;prof().sync='out';document.querySelector('#demoSync').value='out';S.login='start'});
 await T('Вход: инструкция из 3 шагов, «Открыть GitHub», поле-пароль, предупреждение о localStorage',async()=>{await go('login');await shot('230-web-login-token');return await ev(()=>document.querySelectorAll('.tsteps li').length===3&&!!document.querySelector('a[href^="https://github.com/settings/tokens/new"][target=_blank]')&&document.querySelector('#tok').type==='password'&&/localStorage/.test(document.querySelector('.webnote').textContent)&&/чужом/.test(document.querySelector('.webnote').textContent))&&await noHscroll()});
 await T('Показать/скрыть токен',async()=>{await p.locator('#tok').fill('ghp_abc');await click('[data-act=tokEye]');const t1=await ev(()=>document.querySelector('#tok').type);await click('[data-act=tokEye]');return t1==='text'&&await ev(()=>document.querySelector('#tok').type==='password'&&document.querySelector('#tok').value==='ghp_abc')});
 await T('Ошибка: не похоже на токен',async()=>{await p.locator('#tok').fill('hello');await click('[data-act=tokGo]');await shot('231-web-login-token-error');return /не похоже на токен/.test(await txt('#tokErr'))&&await ev(()=>document.querySelector('#tok').getAttribute('aria-invalid')==='true')});
 await T('Ошибка: GitHub не принял токен',async()=>{await p.locator('#tok').fill('ghp_bad123');await click('[data-act=tokGo]');return /не принял токен/.test(await txt('#tokErr'))});
 await T('Ошибка: нет права gist',async()=>{await p.locator('#tok').fill('ghp_noscope1');await click('[data-act=tokGo]');return /нет права gist/.test(await txt('#tokErr'))});
 await T('Вход по верному токену → «Готово»',async()=>{await p.locator('#tok').fill('ghp_good123');await click('[data-act=tokGo]');return /Готово/.test(await txt('.login-card h1'))});
 await T('Сообщество без ключа: «Сообщество недоступно: не задан ключ YouTube» + «Указать ключ»',async()=>{await ev(()=>{S.titleId=2;S.titleTab='community'});await go('title');await ev(()=>{const t=document.querySelector('[data-ttab=community]');t.scrollIntoView({block:'start'});document.querySelector('#main').scrollTop-=60});await p.waitForTimeout(150);await shot('232-web-community-nokey');return /Сообщество недоступно: не задан ключ YouTube/.test(await txt('#cmres .state'))&&!!await ev(()=>document.querySelector('#cmres [data-act=toYtKey]'))});
 await T('«Указать ключ» → настройки, группа YouTube, ключ не задан',async()=>{await click('#cmres [data-act=toYtKey]');await p.waitForTimeout(500);await shot('233-web-settings-ytkey-empty');return await ev(()=>location.hash==='#settings'&&/Не задан/.test(document.querySelector('#ytgroup .kstate').textContent)&&document.querySelector('#ykey').type==='password'&&/localStorage/.test(document.querySelector('#ytgroup .webnote').textContent))&&await noHscroll()});
 await T('Неверный ключ — ошибка',async()=>{await p.locator('#ykey').fill('abc');await click('[data-act=keySave]');await shot('234-web-settings-ytkey-error');return /Ключ не подошёл/.test(await txt('#ytgroup .ferr'))});
 await T('Верный ключ — «Задан · AIza…» и «Удалить ключ»',async()=>{await p.locator('#ykey').fill('AIzaSyD0123456789abcdefghijklmnopqrsXY');await click('[data-act=keySave]');if(shots){await p.waitForTimeout(50);await p.screenshot({path:OUT+'235-web-settings-ytkey-set-'+k+th+'.png'})}return /Задан · AIza…rsXY/.test(await txt('#ytgroup .kstate'))&&!!await ev(()=>document.querySelector('[data-act=keyDel]'))});
 await T('С ключом «Сообщество» показывает ролики',async()=>{await go('title');return await ev(()=>document.querySelectorAll('#cmres .clip').length>=3)});
 await T('Ролик в браузере: «Видео — в приложении» + «Открыть на YouTube»',async()=>{await click('.clip .thumb');await p.waitForTimeout(900);await shot('236-web-video-in-app');return /Видео — в приложении/.test(await txt('.yt-stage'))&&await ev(()=>!!document.querySelector('.yt-stage a[target=_blank]')&&!document.querySelector('.yt-embed'))});
 await T('Серия в браузере: «Видео — в приложении» + «Отметить серию»',async()=>{await ev(()=>{P.clip=null});await go('player');await shot('237-web-episode-in-app');return /Видео — в приложении/.test(await txt('.yt-stage'))&&!!await ev(()=>document.querySelector('.yt-stage [data-act=markEp]'))});
 await T('Трейлер в браузере: «Видео — в приложении»',async()=>{await ev(()=>{P.trailer=true;render()});await p.waitForTimeout(200);const ok=/Видео — в приложении/.test(await txt('.yt-stage'));await ev(()=>{P.trailer=false});return ok});
 await T('Удалить ключ → снова «Не задан»',async()=>{await go('settings');await click('[data-act=keyDel]');return /Не задан/.test(await txt('#ytgroup .kstate'))});
 await T('Сборка «приложение»: нет группы YouTube, вход через код',async()=>{await sel('demoBuild','app');await go('settings');const a=await ev(()=>!document.querySelector('#ytgroup'));await ev(()=>{S.login='start'});await go('login');return a&&await ev(()=>!document.querySelector('#tok'))});
 await T('Приложение без ключа: «Сообщество недоступно» без кнопки',async()=>{await sel('demoCommunity','nokey');await go('title');const ok=/не задан ключ YouTube/.test(await txt('#cmres .state'))&&await ev(()=>!document.querySelector('#cmres [data-act=toYtKey]'));await sel('demoCommunity','ok');return ok});
 const bad=res.filter(r=>r[1]!=='OK');fails+=bad.length;console.log(th,vn,bad.length?bad:'все '+res.length+' OK',errs);await ctx.close();}
await b.close();process.exitCode=fails?1:0;})();
